import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.Aev9KvMf.js";const g=JSON.parse('{"title":"宝宝出生 30 天办事清单 · 出生证/户口/医保/生育津贴","description":"宝宝出生后该办什么、什么时候办：出生医学证明、户口登记、新生儿医保参保（可追溯报销）、生育津贴申领的时间轴与路径。","frontmatter":{"title":"宝宝出生 30 天办事清单 · 出生证/户口/医保/生育津贴","issuer":"依据《户口登记条例》《社会保险法》及各地公开政策整理","source_tier":"一级来源","version":"现行政策","published":2024,"source_url":"https://fuwu.nhsa.gov.cn/","status":"现行","tags":["家庭办事","出生证","户口","生育津贴","新生儿医保","宝宝"],"type":"家庭办事","reviewed":false,"description":"宝宝出生后该办什么、什么时候办：出生医学证明、户口登记、新生儿医保参保（可追溯报销）、生育津贴申领的时间轴与路径。"},"headers":[],"relativePath":"family/baby-checklist.md","filePath":"family/baby-checklist.md"}'),l={name:"family/baby-checklist.md"};function s(i,t,d,n,h,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="宝宝出生-30-天办事清单-·-出生证-户口-医保-生育津贴" tabindex="-1">宝宝出生 30 天办事清单 · 出生证/户口/医保/生育津贴 <a class="header-anchor" href="#宝宝出生-30-天办事清单-·-出生证-户口-医保-生育津贴" aria-label="Permalink to &quot;宝宝出生 30 天办事清单 · 出生证/户口/医保/生育津贴&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据国家法律法规与各地公开政策整理；<strong>时限与材料各地不同</strong>，标待核验处请以当地经办口径为准（热线：12393 医保 / 12333 社保 / 12345 综合）。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家法规与部委政策</strong>，逐条标注出处。这是&quot;事到临头手忙脚乱&quot;型的家庭清单——建议产前收藏。</p></div><h2 id="速览卡-时间轴" tabindex="-1">速览卡（时间轴） <a class="header-anchor" href="#速览卡-时间轴" aria-label="Permalink to &quot;速览卡（时间轴）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时点</th><th>办什么</th></tr></thead><tbody><tr><td><strong>出院前</strong>（在医院）</td><td>出生医学证明申领；乙肝疫苗首针+卡介苗（医院接种，发接种证首剂记录）</td></tr><tr><td><strong>出生 1 个月内</strong></td><td>户口登记（随父随母自愿）</td></tr><tr><td><strong>出生 90 天内</strong>（多地口径，待核验）</td><td>新生儿医保参保——<strong>出生当天的医疗费可按规定追溯报销</strong></td></tr><tr><td><strong>产假期间</strong></td><td>生育津贴（单位申报，与产假工资<strong>就高不重复</strong>）</td></tr></tbody></table><h2 id="分事项指南" tabindex="-1">分事项指南 <a class="header-anchor" href="#分事项指南" aria-label="Permalink to &quot;分事项指南&quot;">​</a></h2><h3 id="_1-出生医学证明" tabindex="-1">① 出生医学证明 <a class="header-anchor" href="#_1-出生医学证明" aria-label="Permalink to &quot;① 出生医学证明&quot;">​</a></h3><ul><li>由<strong>接生机构</strong>签发，多数医院支持出院前办理；新生儿姓名需在办证时确定。</li><li>部分省份已上线<strong>线上申领</strong>（各省政务 App/卫健渠道，待核验）；补办到原签发机构或当地卫健部门。</li><li>多省推行&quot;<strong>出生一件事</strong>&quot;联办：出生证、户口、医保、社保卡一次申请多证联办（国务院推广方向，待核验）——出院前问一句医院或 12345，能省四趟腿。</li></ul><h3 id="_2-户口登记" tabindex="-1">② 户口登记 <a class="header-anchor" href="#_2-户口登记" aria-label="Permalink to &quot;② 户口登记&quot;">​</a></h3><ul><li>依据《中华人民共和国户口登记条例》：<strong>婴儿出生后一个月以内</strong>，由户主、亲属等向<strong>父亲或母亲户籍地派出所</strong>申报（随父随母<strong>自愿</strong>，待核验当地材料清单）。</li><li>常用材料：出生医学证明、父母户口本/身份证、结婚证（非婚生育与落户政策各地不同，待核验）。</li></ul><h3 id="_3-新生儿医保-城乡居民医保-——最容易错过的一项" tabindex="-1">③ 新生儿医保（城乡居民医保）——最容易错过的一项 <a class="header-anchor" href="#_3-新生儿医保-城乡居民医保-——最容易错过的一项" aria-label="Permalink to &quot;③ 新生儿医保（城乡居民医保）——最容易错过的一项&quot;">​</a></h3><ul><li>新生儿<strong>不受居民医保集中缴费期限制</strong>，出生即可参保（待核验当地时限，多地要求出生 <strong>90 天/3 个月内</strong>办理）。</li><li>按时参保的，<strong>出生之日起的医疗费可按规定追溯报销</strong>——新生儿黄疸、住保温箱等费用动辄上万，这一步最值钱。</li><li>参保地：户籍地或父母居住证所在地；线上入口见<a href="/SageRelay/query/yibao.html">国家医保服务平台</a>（App/小程序&quot;新生儿参保&quot;各地入口不同）。</li></ul><h3 id="_4-生育津贴-单位参保职工" tabindex="-1">④ 生育津贴（单位参保职工） <a class="header-anchor" href="#_4-生育津贴-单位参保职工" aria-label="Permalink to &quot;④ 生育津贴（单位参保职工）&quot;">​</a></h3><ul><li>由<strong>用人单位</strong>向医保经办机构申报（个人一般不能直接办，待核验各地细则）；灵活就业/居民医保参保者按当地生育保障政策执行（待核验）。</li><li>逻辑：生育津贴 = 单位上年度月平均工资 ÷ 30 × 产假天数（待核验）；<strong>与产假工资就高发放、不重复</strong>。</li><li>产假天数：国家基础产假 98 天 + 各省奖励假（各省 30～90 天不等，<strong>总天数以本省人口与计划生育条例为准</strong>）。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确说法</th></tr></thead><tbody><tr><td>&quot;出生证晚点办没关系&quot;</td><td>后续户口、医保、补贴全挂在出生证上，越早办越顺</td></tr><tr><td>&quot;新生儿不用急着上医保&quot;</td><td>90 天（多地口径）内参保才能<strong>追溯报销出生当天起的费用</strong>，超期就只能等下一年度（待核验）</td></tr><tr><td>&quot;生育津贴是打卡给个人的现金福利&quot;</td><td>原则上由<strong>单位申报</strong>、与产假工资衔接——离职/断保前先问清自己那笔怎么领（待核验）</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>报销资格：<a href="/SageRelay/query/yibao.html">医保定点机构查询</a> · <a href="/SageRelay/query/yibao-drug.html">医保药品目录</a></li><li>妈妈的权益：<a href="/SageRelay/data/minimum-wage-2026.html">各地最低工资</a>（产假工资下限参考）· <a href="/SageRelay/social/pension-after-death.html">养老金身故权益</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>法规</td><td>《中华人民共和国户口登记条例》；《社会保险法》（生育保险并入职工医保后的待遇框架，待核验）</td></tr><tr><td>政策</td><td>新生儿&quot;出生一件事&quot;联办（国务院推进，待核验）；各地产假与津贴细则</td></tr><tr><td>热线</td><td>12393（医保）· 12333（社保）· 12345（综合/出生一件事）</td></tr></tbody></table>',20)])])}const b=a(l,[["render",s]]);export{g as __pageData,b as default};
